import{_ as r,C as t,o,c as s,E as a,a2 as c}from"./chunks/framework.DyLyN3RJ.js";const b=JSON.parse('{"title":"An Approval Prompt Is Only One Part of Delegated Authority","description":"","frontmatter":{"title":"An Approval Prompt Is Only One Part of Delegated Authority","article_type":"engineering-insight","edition":"research-center","research_question":"动作前的人工批准能说明什么，委派权限还需要哪些证据？","summary":"Pinned source-function probes show how approval changes action disposition, while leaving caller identity, authority scope and policy coverage as separate evidentiary questions.","sources":"Salesforce Help; MCP draft authorization and security guidance; AgentSpec v3 and pinned source","date":"2026-11-12","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261112-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-12-sig-20261112-002-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-11-12-sig-20261112-002.md","filePath":"en/industry/2026-11-12-sig-20261112-002.md","lastUpdated":1794485478000}'),l={name:"en/industry/2026-11-12-sig-20261112-002.md"};function d(p,e,h,u,f,g){const n=t("ArticleCover"),i=t("ArticleTableScroll");return o(),s("div",null,[a(n,{image:"/assets/covers/daily-2026-11-12-sig-20261112-002-cover.png",kicker:"Research",title:"An Approval Prompt Is Only One Part of Delegated Authority",summary:"Pinned source-function probes show how approval changes action disposition, while leaving caller identity, authority scope and policy coverage as separate evidentiary questions.",version:"2026-11-12",languageHref:"/zh/industry/2026-11-12-sig-20261112-002",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=c('<h1 id="an-approval-prompt-is-only-one-part-of-delegated-authority" tabindex="-1">An Approval Prompt Is Only One Part of Delegated Authority <a class="header-anchor" href="#an-approval-prompt-is-only-one-part-of-delegated-authority" aria-label="Permalink to &quot;An Approval Prompt Is Only One Part of Delegated Authority&quot;">​</a></h1><p>After a human approves, the executor continues the original action. That is a specific promise that code can test. Saying that a delegated invocation was correctly authorized requires more: who initiated it, what the approval covered, and whether the action passed the applicable checks. A confirmation prompt cannot supply all those connections by itself.</p><p>This study places that distinction against a bounded execution result. In selected functions from a pinned AgentSpec revision, agreement continues the same action, refusal skips it, and empty or nontriggering rules preserve the action. Our interpretation is that action approval, policy coverage and caller authority need separate evidence. This neither certifies a complete platform nor alleges a bypass in a deployed product.[1][2]</p><h2 id="what-actually-continues-after-confirmation" tabindex="-1">What actually continues after confirmation <a class="header-anchor" href="#what-actually-continues-after-confirmation" aria-label="Permalink to &quot;What actually continues after confirmation&quot;">​</a></h2><p>In the inspected synchronous source path, constraint checking precedes actual action execution. The human-inspection function receives an action, asks the user and returns a disposition. The same-day analysis extracted and executed selected functions at commit <code>e6fa3902e2cfb9681f454b355691b771f70543f8</code>. This is the registered baseline revision, not an assertion about current HEAD or the exact paper release.[1]</p><p>The internal experimental evidence covers five approval-input cases and six dispatch cases. Action, Rule, RuleInterpreter and state were disclosed test doubles. Real domain predicates, adapters and LangChain were not executed. This is a source-derived isolated function probe, not a full-system reproduction.[2]</p><table tabindex="0"><thead><tr><th>Input or condition</th><th>Internal probe observation</th><th>Supported reading</th></tr></thead><tbody><tr><td>yes, or y surrounded by whitespace</td><td>Continue with the same action object</td><td>Agreement does not replace the action in this function</td></tr><tr><td>no or n</td><td>Skip with a skip action</td><td>The function can suppress this action</td></tr><tr><td>Invalid input followed by yes</td><td>Two prompts, then the original action</td><td>Invalid input does not directly authorize continuation</td></tr><tr><td>Triggered rule with injected continue, skip or stop result</td><td>Original action, skip action or finish action respectively</td><td>Dispatch follows the supplied interpreter result</td></tr><tr><td>Nontriggering rule or empty rule list</td><td>Original action retained</td><td>Suppression depends on coverage and triggering</td></tr><tr><td>Missing rules value</td><td>Exception stating that rules must not be none</td><td>An empty list and absent rules are different paths</td></tr></tbody></table><p>All table entries are internal isolated-function observations, not independent third-party validation or samples of real user invocations. Continue, skip and stop outcomes were supplied by the interpreter double. Correct dispatch therefore says nothing by itself about whether a real predicate evaluates correctly.[2]</p><p>Object identity establishes only a return relationship in this synchronous call. The probe did not test concurrent mutation, changes after approval, asynchronous calls or recovery. Translating “the same object continues” into “approved content always equals executed content” would exceed the evidence.</p><h2 id="a-check-exists-coverage-remains-a-separate-question" tabindex="-1">A check exists; coverage remains a separate question <a class="header-anchor" href="#a-check-exists-coverage-remains-a-separate-question" aria-label="Permalink to &quot;A check exists; coverage remains a separate question&quot;">​</a></h2><p>Empty and nontriggering rules are necessary controls. They show why the presence of a checking call does not establish that every action requiring restriction is caught by an effective rule. Assessing protection for an action still requires the applicable rule, its trigger, the state read by its predicate and the eventual execution point. Only a small part of that chain was executed here.</p><p>The AgentSpec paper describes trigger, predicate and enforcement mechanisms, with checks at action, state and finish boundaries; the reported integration uses LangChain 0.3.13. That description supports discussion of where to inspect. It cannot supply missing audits of interpreters, domain adapters or asynchronous paths.[3]</p><p>The paper also reports costs and differences in coverage: safe embodied-task fulfillment falls from 58.62% to 54.26%; generated rules prevent five of eight driving violations, while manual rules achieve complete compliance in the tested scenarios. These are author-reported results under the stated experiments, not our reruns. They motivate evaluating rule selection rather than reading the existence of a constraint mechanism as a guarantee that every task completes safely.[3]</p><h2 id="organizational-relationships-tokens-and-answers-do-different-jobs" tabindex="-1">Organizational relationships, tokens and answers do different jobs <a class="header-anchor" href="#organizational-relationships-tokens-and-answers-do-different-jobs" aria-label="Permalink to &quot;Organizational relationships, tokens and answers do different jobs&quot;">​</a></h2><p>Salesforce&#39;s Help article describes parent-planner delegation within one organization, explicit relationships across organizations, and per-agent gateway controls. These are vendor capability descriptions. The captured material does not provide the delegated credential scope, token trace or execution evidence needed to verify an individual invocation. Organizational relationships alone cannot establish that each tool call has been correctly authorized.[4]</p><p>The captured MCP draft addresses a different responsibility. Authorization is optional in that draft; HTTP implementations supporting it should follow the specified flow, while STDIO should obtain credentials from the environment. For requests using the authorization flow, resource servers must validate tokens for their own audience. The security requirements additionally call for separate upstream API tokens and prohibit passing the client token through.[5][6]</p><p>The captured security guidance treats state handles as ordinary tool arguments. They cannot authenticate callers and should be bound server-side to a verified principal. Guessing a handle should not authorize access to another user&#39;s state. This is a normative obligation, not a measurement that a particular service implements it correctly.[7]</p><p>These materials can be compared by responsibility, but cannot be assembled into an integration test that never happened. Organizational relationships describe collaboration; token audience and upstream credential restrictions define resource boundaries; state binding concerns ownership of state; a human answer decides the action at the observed checkpoint. Only the last received isolated branch execution here. Descriptions and obligations in the other layers cannot substitute for that execution evidence, and the local probe cannot validate those layers in return.</p><p>Our engineering interpretation is to ask separately how the caller is established, how action and resource scope are restricted, which action occurrence an approval refers to, and whether all actual execution paths encounter the applicable rules. These are inspection questions derived from the evidence, rather than an implemented or validated complete authorization design.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>Public primary-source facts here describe what a specification or pinned source says. Source-reported claims remain attributed to vendors and authors. Our observations and internal experiments cover only inspected code and selected executed functions. Our interpretation separates responsibilities that need verification. No independent third party examined the complete delegation chain discussed here. Citation is not endorsement, peer review is not proof, and self-reported evidence is not independent evidence. Publication or successful implementation does not establish general validity.</p><ol><li>AgentSpec authors, pinned source files <code>controlled_agent_excector.py</code> and <code>enforcement.py</code>, registered baseline commit <code>e6fa3902e2cfb9681f454b355691b771f70543f8</code>, local snapshot read on 2026-11-12. <a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/controlled_agent_excector.py" target="_blank" rel="noreferrer">Executor</a>; <a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/enforcement.py" target="_blank" rel="noreferrer">human inspection</a>.</li><li>Research Center, <a href="/joinwell52/assets/evidence/2026-11-12-sig-20261112-002/002-experiment.json">internal isolated-function experimental record, 2026-11-12</a>: five approval and six dispatch cases. Disclosed doubles, inputs, outputs and limits are retained in the experimental record bound to the same-day Research Object. This is neither a public-product test nor third-party reproduction.</li><li>AgentSpec authors, <em>Customizable Runtime Enforcement for Safe and Reliable LLM Agents</em>, research paper v3, mechanism and Tables 4–6, snapshot read on 2026-11-12. <a href="https://arxiv.org/html/2503.18666v3" target="_blank" rel="noreferrer">Paper</a>.</li><li>Salesforce, Help documentation on single-organization and multi-organization collaboration and Agent Gateway, snapshot read on 2026-11-12. <a href="https://help.salesforce.com/s/articleView?id=005317683&amp;language=en_US&amp;type=1" target="_blank" rel="noreferrer">Help article</a>.</li><li>MCP project, draft authorization specification, scope, protocol requirements and token handling, captured on 2026-11-12; a mutable draft. <a href="https://modelcontextprotocol.io/specification/draft/basic/authorization.md" target="_blank" rel="noreferrer">Authorization</a>.</li><li>MCP project, draft authorization security considerations, audience binding and privilege restriction, captured on 2026-11-12. <a href="https://modelcontextprotocol.io/specification/draft/basic/authorization/security-considerations.md" target="_blank" rel="noreferrer">Security requirements</a>.</li><li>MCP project, draft security best practices, state-handle hijacking guidance, captured on 2026-11-12. <a href="https://modelcontextprotocol.io/docs/draft/tutorials/security/security_best_practices.md" target="_blank" rel="noreferrer">Security guidance</a>.</li></ol><h2 id="a-local-check-may-suffice-distributed-bindings-remain-unestablished" tabindex="-1">A local check may suffice; distributed bindings remain unestablished <a class="header-anchor" href="#a-local-check-may-suffice-distributed-bindings-remain-unestablished" aria-label="Permalink to &quot;A local check may suffice; distributed bindings remain unestablished&quot;">​</a></h2><p>A synchronous local approval can be entirely adequate for a single-user threat model. Absence of distributed approval records in the inspected files does not establish that the complete system lacks those controls. Untested paths cannot be described as vulnerabilities.</p><p>What remains unestablished is how a child action binds to its initiating principal, task occurrence and approval occurrence; how revoked grants affect long-running delegation; and whether asynchronous, tool-internal and recovery paths encounter equivalent constraints. Answering those questions requires evidence from the relevant paths and credentials. The present boundary is narrower: approval changed action disposition in the tested functions, while delegated authority still needs its own supporting evidence.</p>',25))])}const y=r(l,[["render",d]]);export{b as __pageData,y as default};
